func:
const errorFlag = flow.get("errorFlag") || false;
if (!errorFlag) {
    flow.set("errorFlag", true)
};
msg.delay = 10000;  // 10 seconds between retry
return msg;

// get errorFlag
const errorFlag = flow.get('errorFlag') || false;

// if errorFlag is True, do nothing and set errorFlag to false
if (errorFlag) {
    flow.set('errorFlag', false)
    return null
} else {
    msg.topic = 'control'
    msg.payload = 'peek'
    return msg
}

// Combine the error message and the queueText

const errorMessage = msg.error.message;
const queueText = flow.get("queueText") || "Queue: 0";
const combinedMessage = `${queueText} - ${errorMessage}`
node.status({ fill: "red", shape: "ring", text: combinedMessage});

// Set the Flow status to the status message of the q-gate
const queueText = flow.get("queueText") || "Queue: 0";
node.status({ fill: "yellow", shape: "ring", text: queueText});

// Reset the trigger and set the delay to high value to avoid
// peeking the same message from the queue again,
// if the database is not responding within a few seconds

msg.reset = true;
return msg;

// Get stored file
const fileData = flow.get('leather_uploadedFile');
const fileName = flow.get('leather_fileName');

if (!fileData) {
    msg.payload = '❌ Brak pliku do przetworzenia';
    msg.topic = 'error';
    return [null, msg];
}

msg.payload = fileData;
msg.filename = fileName;
msg.topic = 'process_file';

const statusMsg = {
    payload: '🔄 Przetwarzanie rozpoczęte...',
    topic: 'processing'
};

return [msg, statusMsg];

// Save file in flow context
if (msg.payload && msg.payload.length > 0) {
    flow.set('leather_uploadedFile', msg.payload);
    flow.set('leather_fileName', msg.file.name || 'uploaded.xlsx');

    // Validate file type
    const fileName = msg.file.name || '';
    const validExtensions = ['.xlsx', '.xls', '.XLSX'];
    const isValid = validExtensions.some(ext => fileName.toLowerCase().endsWith(ext));

    if (isValid) {
        msg.payload = `✅ Plik "${fileName}" został załadowany`;
        msg.topic = 'file_ready';
        return [msg, null];
    } else {
        msg.payload = `❌ Nieprawidłowy typ pliku. Dozwolone są tylko pliki .xlsx i .xls.`;
        msg.topic = 'file_error';
        return [null, msg];
    }
} else {
    msg.payload = 'Nie wybrano pliku';
    msg.topic = 'no_file';
    return [null, msg];
}

/*
Constant values:
- All `Deliveries.type = "incoming"`
- All `Tours.id = tour_number + "_4000"`

---

*/

const pages = msg.payload;
const rows = []
const schema = "leather_receipt";  // schema name

// --- Collect affected pk-values ---
const tourIds = new Set();
const vbelnIds = new Set();
const deliveryIds = new Set();
const aufnrIds = new Set();


let queries = [];  // For SQL Queries
let tableData = [];  // For UI

// --- Helpful functions ---

function formatDateForTour(isoDateString) {
    try {
        const date = new Date(isoDateString);
        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        return `${day}.${month}.${year}`;  // Format: DD.MM.YYYY
    } catch (err) {
        return null;
    }
}

function toSqlDate(isoString) {
    try {
        return new Date(isoString).toISOString().split('T')[0];  // 'YYYY-MM-DD'
    } catch (e) {
        return null;
    }
}

function hasError(val) {
    if (typeof val !== 'string') return false;
    return val.includes('#ERROR') || val.includes('#N/A');
}

/**
 * Validates and normalizes tour_number from Excel.
 * 
 * @param {any} tourNumber - The raw tour_number value from Excel
 * @param {number} rowIndex - Row index for error reporting (1-based)
 * @returns {Object} - { success: boolean, value: number|null, error: string|null }
 * 
 * Validation rules:
 * - If number or numeric string → parse and return as number
 * - If contains "SHOP" or "shop" → return 999999
 * - Otherwise → return error
 */
function validateTourNumber(tourNumber, rowIndex) {
    // Already a valid number
    if (typeof tourNumber === 'number') {
        return { success: true, value: tourNumber, error: null };
    }

    // Handle string values
    if (typeof tourNumber === 'string') {
        // Try to parse as number
        const parsed = parseInt(tourNumber, 10);
        if (!isNaN(parsed)) {
            return { success: true, value: parsed, error: null };
        }

        // Check for "SHOP" keyword (case-insensitive)
        if (tourNumber.toLowerCase().includes('shop')) {
            return { success: true, value: 999999, error: null };
        }
    }

    // Invalid tour number - return error
    return {
        success: false,
        value: null,
        error: `❌ Error: Invalid tour_number in row ${rowIndex} (Tour: ${tourNumber})`
    };
}

// The following for loop iterates over all pages and its rows.
// It starts at page 0 (page 1) and row 1 (row 2 in excel)
for (let i = 0; i < pages.length; i++){
    for (let a = 1; a < pages[i].length; a++)
        rows.push(pages[i][a]);
}

// Iterate over the new created array with all rows
for (let i = 0; i < rows.length; i++) {
    const row = rows[i];

    const delivery_id = row[1];
    const delivery_pos = row[2];
    const vbeln_id = row[3];
    const aufnr_name = row[5];
    const tour_number = row[7];
    const tour_date_raw = row[8];
    const aufnr_id = row[10];

    const requiredValues = [delivery_id, delivery_pos, vbeln_id, aufnr_name, tour_number, tour_date_raw, aufnr_id];

    // Helper: treat null, undefined, empty string as empty
    const isEmpty = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');

    // 1. Skip if ALL positions are empty
    if (requiredValues.every(isEmpty)) {
        continue; // go to next row
    }

    // 2. Error if SOME but not all are empty or faulty
    if (requiredValues.some(isEmpty) || requiredValues.some(v => hasError(v))) {
        node.warn(`Error: Incomplete or invalid data in Excel row ${i + 1}`);
        return [
            null,
            { payload: [] },  // Reset the JOIN Node
            { topic: 'error', payload: `❌ Error: Missing or invalid data in row ${i + 1} (Dostawa: ${delivery_id})` }
        ];
    }

    // 3. Validate and normalize tour_number
    const tourValidation = validateTourNumber(tour_number, i + 1);
    if (!tourValidation.success) {
        node.warn(tourValidation.error);
        return [
            null,
            { payload: [] },  // Reset the JOIN Node
            { topic: 'error', payload: tourValidation.error }
        ];
    }
    const validated_tour_number = tourValidation.value;

    // 4. Process as normal below
    const tour_date_formatted = formatDateForTour(tour_date_raw);
    const tour_date = toSqlDate(tour_date_raw);

    // 1. Insert Tour
    const tour_id = `${validated_tour_number}_${tour_date_formatted}_4000`;
    if (!tourIds.has(tour_id)) {
        queries.push(
            `INSERT INTO ${schema}.tour (id, tour_number, mbdat, state) VALUES ('${tour_id}', ${validated_tour_number}, '${tour_date}', 'open') ON CONFLICT (id) DO UPDATE SET tour_number = EXCLUDED.tour_number, mbdat = EXCLUDED.mbdat, state = EXCLUDED.state;`
        );
        tourIds.add(tour_id);
    }

    // 2. Insert Vbeln
    if (!vbelnIds.has(vbeln_id)) {
        queries.push(
            `INSERT INTO ${schema}.vbeln (id, name, tour_id, state) VALUES (${vbeln_id}, 'vbeln_${vbeln_id}', '${tour_id}', 'open') ` +
            `ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, tour_id=EXCLUDED.tour_id, state=EXCLUDED.state;`
        );
        vbelnIds.add(vbeln_id);
    }

    // 3. Insert Deliveries
    if (!deliveryIds.has(delivery_id)) {
        queries.push(
            `INSERT INTO ${schema}.deliveries (id, state, type) VALUES (${delivery_id}, 'loaded', 'incoming') ` +
            `ON CONFLICT (id) DO UPDATE SET state=EXCLUDED.state, type=EXCLUDED.type;`
        );
        deliveryIds.add(delivery_id);
    }

    // 4. Insert Aufnr
    queries.push(
        `INSERT INTO ${schema}.aufnr (id, name, delivery_id, delivery_pos, vbeln_id, state, created_at, updated_at) ` +
        `VALUES (${aufnr_id}, '${aufnr_name}', ${delivery_id}, ${delivery_pos}, ${vbeln_id}, 'loaded', NOW(), NOW()) ` +
        `ON CONFLICT (id) DO UPDATE SET ` +
        `name=EXCLUDED.name, ` +
        `delivery_id=EXCLUDED.delivery_id, ` +
        `delivery_pos=EXCLUDED.delivery_pos, ` +
        `vbeln_id=EXCLUDED.vbeln_id, ` +
        `state=EXCLUDED.state, ` +
        `updated_at=NOW();`
    );
    aufnrIds.add(aufnr_id);

    // Add table data for UI
    tableData.push({
        delivery_id: delivery_id,
        delivery_pos: delivery_pos,
        ta: vbeln_id,
        tour: validated_tour_number,
        tour_date: tour_date,
        production_order: aufnr_id,
        production_order_name: aufnr_name
    });
}

msg.query = queries.join("\n")

// Multi-output return
if (queries.length > 0) {
    node.send(
        [
            { query: queries.join("\n") },
            null,
            null
        ]
    );
};

// Send all the table data after successfull processing
for (let i = 0; i < tableData.length; i++) {
    node.send(
        [
            null,
            { payload: tableData[i] },
            null
        ]
    );
}
node.send(
    [
        null,
        null,
        { complete: true },
    ]
);

// Reset the flow variables
flow.set('leather_uploadedFile', null);
flow.set('leather_fileName', null);

// Prepare HTTP POST request
msg.method = "POST";
msg.url = "http://srem-svr-lin01.srem.polipol.intra/test/api/leather_receipt/excel_import";
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = {
    state: "success"
};

return msg;

